import { expect, test, type APIRequestContext } from "@playwright/test";
import { investigations, waitEnded } from "./support";

// An investigation an A2A task started: the pages name the trigger and the client. The
// protocol itself is tested with the official A2A SDK (backend/e2e); this sends the
// JSON-RPC request `make replay` prints.

/** The token of the end-to-end A2A client `e2e-agent-a`, generated by `make e2e`. */
function token(): string {
  const value = process.env.BIANQUE_E2E_A2A_TOKEN;
  if (!value) throw new Error("BIANQUE_E2E_A2A_TOKEN is not set; run the tests with make e2e");
  return value;
}

async function startTask(request: APIRequestContext, caseId: string): Promise<string> {
  const response = await request.post("/a2a", {
    headers: { Authorization: `Bearer ${token()}`, "A2A-Version": "1.0" },
    data: {
      jsonrpc: "2.0",
      id: 1,
      method: "SendMessage",
      params: {
        message: { messageId: "1", role: "ROLE_USER", parts: [{ data: { case_id: caseId } }] },
        configuration: { returnImmediately: true },
      },
    },
  });
  expect(response.ok()).toBe(true);
  const body = (await response.json()) as { result: { task: { metadata: { investigation_id: string } } } };
  return body.result.task.metadata.investigation_id;
}

test("an investigation an A2A task started names the trigger and the client", async ({ page }) => {
  const id = await startTask(page.request, "s1-c");
  expect((await waitEnded(page.request, id)).investigation.status).toBe("reported");

  await page.goto(`/investigations/${id}`);
  const card = page.getByTestId("alert-card");
  await expect(card).toContainText("触发：A2A");
  await expect(card).toContainText("调用方 e2e-agent-a");
  for (const width of [1440, 390]) {
    for (const scheme of ["light", "dark"] as const) {
      await page.setViewportSize({ width, height: 900 });
      await page.emulateMedia({ colorScheme: scheme });
      await page.waitForLoadState("networkidle");
      await page.screenshot({ path: `e2e/screenshots/detail-a2a-${width}-${scheme}.png`, fullPage: true });
    }
  }

  const listed = (await investigations(page.request)).find((item) => item.id === id);
  expect(listed?.trigger).toBe("a2a");
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto("/");
  await expect(page.getByTestId("investigation-row").filter({ hasText: id })).toContainText("A2A · s1-c");
});
